entrypoint: loadMatrixDeliveryPlan from extensions/matrix/src/matrix/delivery-plan.ts
boundary: real plugin blob-store boundary
base 4cf81a5c196e331f4eacb038c964d337af88d146: valid-control=accepted; corrupt-plan=accepted body=durable� hello
head 5d63046326efd4c885e30e1351c1ceda1dbffc43: valid-control=accepted; corrupt-plan=rejected error=Matrix durable delivery plan is invalid JSON
negative-control: valid-control=accepted on exact HEAD
